def count_passing_ways(n: int, m: int) -> int:
    if n == 1 or m == 0:
        return 1
    if m == 1:
        return n
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[m % n]
