def max_energy(beads):
    n = len(beads)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(i, n):
            if beads[i] == beads[j]:
                dp[i][j] = beads[i] * beads[j] * (j - i + 1)

    for size in range(2, n + 1):
        for i in range(n - size + 1):
            j = i + size - 1
            dp[i][j] = max(dp[i][k] + dp[k + 1][j] for k in range(i, j))

    return dp[0][n - 1]
```
