def decode(encoded, original, message):
    # Initialize an empty dictionary to map encoded letters to original letters
    mapping = {}

    # Iterate over the encoded string
    for i in range(len(encoded)):
        # If the encoded letter is not already in the mapping, add it to the mapping
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        # If the encoded letter is already in the mapping and the corresponding original letter is different, the decoding is not possible
        elif mapping[encoded[i]] != original[i]:
            return "Failed"

    # Initialize an empty string to store the decoded message
    decoded = ""

    # Iterate over the encrypted message
    for letter in message:
        # If the letter is in the mapping, add the corresponding original letter to the decoded message
        if letter in mapping:
            decoded += mapping[letter]
        # If the letter is not in the mapping, add it to the decoded message without changes
        else:
            decoded += letter

    return decoded
