def count_sequences(n, last, memo):
    if n == 1 and last == 1:
        return 1
    if n == 0:
        return 0
    if last > n:
        return 0
    if last in memo:
        return memo[last]
    result = 0
    for i in range(1, last//2+1):
        result += count_sequences(n-1, i, memo)
    memo[last] = result
    return result
